import{_ as o,o as a,c as t,ag as d}from"./chunks/framework.BaNuf0sO.js";const g=JSON.parse('{"title":"ModalPorter（弹窗注册表·命令式拉起）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/modal/docs/README-ModalPorter.md","filePath":"docs/core/src/components/modal/docs/README-ModalPorter.md"}'),l={name:"docs/core/src/components/modal/docs/README-ModalPorter.md"};function s(r,e,c,p,i,n){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="modalporter-弹窗注册表·命令式拉起" tabindex="-1">ModalPorter（弹窗注册表·命令式拉起） <a class="header-anchor" href="#modalporter-弹窗注册表·命令式拉起" aria-label="Permalink to &quot;ModalPorter（弹窗注册表·命令式拉起）&quot;">​</a></h1><blockquote><p>弹窗注册表：<code>modalList</code> 声明 key → 组件 → 架子，<code>evoke(key, payload)</code> 命令式拉起；nsKey 命名空间 + 失活/卸载自动清理。 范式页：<code>apps/reference/src/pages/modal/porter/showcase/</code>（三层自定义架子 + 触发按钮组）、<code>apps/reference/src/pages/modal/guide/</code>（对接内置 page 架子）</p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>何时用</strong>：代码任意位置需要命令式拉起弹窗（列表行操作、深层组件内触发），且弹窗有「开弹窗」层级诉求时</li><li><strong>何时不用</strong>：模板内直接挂载的弹窗（<code>v-model:show</code> 声明式）不需要 Porter；无嵌套的单层弹窗直接用 ModalConfirm/ModalForm/ModalDetail</li><li>职责边界：Porter 是「注册表 + 拉手」——<code>modalList</code> 把 key 与弹窗组件/懒工厂/架子绑定，<code>evoke</code> 沿 key 查表拉起并把 payload 注入弹窗 props；弹窗实例落在 ModalShelf 架子上</li><li>命名空间：每个 Porter 实例的注册 key 会被包装为 <code>p{porterUid}:{key}</code>——多 Porter 实例同 key 不互踩</li></ul><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><p>对接内置 page 架子（<code>modal/guide/config.tsx</code>——<code>shelf</code> 传字符串 <code>&quot;page&quot;</code> 即指 AppPage 内置架子）：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> modalList</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> RegisterEntry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { key: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;standardDetailSpace&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">component</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./modal/Index.vue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), shelf: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;page&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p><strong>要点</strong>：</p><ul><li><code>modalList</code> 注册项：<code>{key, component | 懒工厂, shelf, sameKeyStrategy?}</code>——<code>shelf</code> 传 <code>&quot;app&quot;</code>/<code>&quot;page&quot;</code> 字符串寻址内置架子，custom 级传 <code>ShelfInstance</code>（ref 的架子实例）</li><li><code>evoke(key, payload)</code>：key 必须在 <code>ModalShelfMap</code> 声明合并中注册（类型化），payload 形状全链推导；未配置的 key 或找不到架子 → <code>console.error</code> + 返回 <code>null</code></li><li>弹窗组件侧声明 <code>ModalInjectedProps&lt;P&gt;</code>：<code>{show, closeFn, removeFn, payload}</code>——show 受架子控，closeFn 挂 <code>onUpdate:show</code> 即可命令式关闭</li><li>生命周期：Porter 失活/卸载时自动 remove 本 porter 注册的全部 nsKey（useActivated 统一收口）——<strong>[MUST NOT]</strong> 手动补偿清理</li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong>默认即够用：对接内置 page 架子</strong>——列表行操作/深层组件内命令式拉起，<code>shelf: &quot;page&quot;</code> 即指 AppPage 内置架子，零自定义架子。</li><li><strong>懒工厂按需</strong>：<code>component: () =&gt; import(...)</code> 按需加载（推荐默认）；仅当弹窗必须随页面首屏就位时才直接传组件对象。</li><li><code>sameKeyStrategy</code>：默认 <code>&quot;recreate&quot;</code>（同 key 再 evoke 关旧重建）即够用；<code>&quot;update&quot;</code>（已开则整体替换 props 不 remount）仅当同 key 弹窗需要原位刷新数据时选。</li><li><code>shelf: &quot;custom&quot;</code>：仅当 app/page 两层不够（第三层以上）时才传 <code>ShelfInstance</code> 自建 custom 架子（判据见 ModalShelf 能力边界）。</li><li><strong>完整能力演示</strong>（三层自定义架子 + 触发按钮组 + 多 key 注册）：<code>apps/reference/src/pages/modal/porter/showcase/</code>、<code>apps/reference/src/pages/modal/guide/</code>——能力展示，非推荐默认。</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>modalList</code></td><td><code>RegisterEntry[]</code>（必传）</td><td>—</td><td>弹窗注册表（key → component/懒工厂 → shelf → sameKeyStrategy）</td></tr><tr><td><code>globalOnly</code></td><td><code>symbol</code>（core 内部专用）</td><td>无默认</td><td><strong>专用模式标识</strong>：仅 AppLayout 内部调用时传（<code>APP_GLOBAL_MODAL_PORTER_SYMBOL</code>，core 内部不导出）——只接受 <code>shelf:&quot;app&quot;</code> 条目推送，非 app 条目 <code>console.error</code> + 过滤；外部 [MUST NOT] 使用（Symbol 拿不到即无法误用）</td></tr></tbody></table><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td>默认</td><td>无</td><td>页面内容透传</td></tr></tbody></table><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><table tabindex="0"><thead><tr><th>成员</th><th>签名</th><th>语义</th></tr></thead><tbody><tr><td><code>evoke</code></td><td><code>&lt;K extends keyof ModalShelfMap&gt;(key: K, payload: ModalShelfMap[K]) =&gt; EvokeHandle | null</code></td><td>按 key 拉起弹窗（payload 类型全链推导）；未配置/找不到架子 → console.error + null</td></tr></tbody></table><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="modallist-注册表寻址" tabindex="-1">modalList 注册表寻址 <a class="header-anchor" href="#modallist-注册表寻址" aria-label="Permalink to &quot;modalList 注册表寻址&quot;">​</a></h3><p><code>RegisterEntry&lt;K&gt;</code>：<code>{key, component | 懒工厂, shelf: &quot;app&quot;|&quot;page&quot;|ShelfInstance, sameKeyStrategy?}</code>——setup 期同步 inject app/page 控制器并缓存；<code>shelf:&quot;app&quot;</code>/<code>&quot;page&quot;</code> 字符串寻址内置架子，custom 经 <code>ShelfInstance</code> ref 直取。懒工厂写法 <code>() =&gt; import(&quot;./modal/Index.vue&quot;)</code> 按需加载。</p><h3 id="nskey-命名空间" tabindex="-1">nsKey 命名空间 <a class="header-anchor" href="#nskey-命名空间" aria-label="Permalink to &quot;nsKey 命名空间&quot;">​</a></h3><p>每个 Porter 实例把注册 key 包装为 <code>p{porterUid}:{key}</code>——多 Porter 实例（多页面/多架子）同 key 不互踩；evoke/remove 都以命名空间后的 nsKey 寻址，业务无需感知。</p><h3 id="卸载自动清理" tabindex="-1">卸载自动清理 <a class="header-anchor" href="#卸载自动清理" aria-label="Permalink to &quot;卸载自动清理&quot;">​</a></h3><p>失活/卸载时自动 remove 本 porter 注册的全部 nsKey（useActivated 统一收口）——Porter 销毁即弹窗实例随架清理，<strong>[MUST NOT]</strong> 手动补偿清理。</p><h3 id="专用模式-globalonly-applayout-内部全局弹窗-porter" tabindex="-1">专用模式（<code>globalOnly</code>：AppLayout 内部全局弹窗 Porter） <a class="header-anchor" href="#专用模式-globalonly-applayout-内部全局弹窗-porter" aria-label="Permalink to &quot;专用模式（`globalOnly`：AppLayout 内部全局弹窗 Porter）&quot;">​</a></h3><p>AppLayout 在调用内置 app 级 ModalShelf 的<strong>子元素最前</strong>位置调用一个打 <code>globalOnly</code> 标识的专用 Porter，配置数据直接来自 AppLayout 的 <code>globalModalConfig</code> prop——<strong>全局弹窗的唯一注册入口</strong>。专用模式下：</p><ul><li>只接受 <code>shelf:&quot;app&quot;</code> 条目；<strong>非 app 条目（page/custom）<code>console.error</code> + 过滤</strong>——page 级弹窗注册不得逃逸到全局面（page 级作用域由路由层保证）；</li><li>推送的配置落到 app 级架子 → 挂载进 <code>globalModalRemote</code>（经 AppLayout <code>v-model:globalModalRemote</code> → 内置架子 <code>v-model:remote</code>），应用根即可遥控；</li><li>专用 Porter 生命周期与 AppLayout 同寿——<strong>规避页面级 Porter 配 app 级弹窗的孤儿弹窗反模式</strong>（页面卸载后弹窗还挂在常驻 app 架子上、句柄丢失）。</li></ul><h3 id="注入给弹窗的-props-modalinjectedprops-p" tabindex="-1">注入给弹窗的 props（<code>ModalInjectedProps&lt;P&gt;</code>） <a class="header-anchor" href="#注入给弹窗的-props-modalinjectedprops-p" aria-label="Permalink to &quot;注入给弹窗的 props（`ModalInjectedProps&lt;P&gt;`）&quot;">​</a></h3><p>架子把 <code>{show, closeFn, removeFn, payload: P}</code> 注入弹窗组件（见 ModalShelf 文档）。</p><h3 id="放进-apppage-方位槽-⇒-挂载时一条指名道姓的-console-error" tabindex="-1">放进 <code>AppPage</code> 方位槽 ⇒ 挂载时一条指名道姓的 <code>console.error</code> <a class="header-anchor" href="#放进-apppage-方位槽-⇒-挂载时一条指名道姓的-console-error" aria-label="Permalink to &quot;放进 `AppPage` 方位槽 ⇒ 挂载时一条指名道姓的 `console.error`&quot;">​</a></h3><p><code>AppPage</code> 的 <code>#top</code> / <code>#bottom</code> / <code>#left</code> / <code>#right</code> 是<strong>方位槽</strong>（fixed 悬浮区）， 它们是页面内置 <code>ModalShelf</code> 的<strong>兄弟节点</strong>而不是后代 ⇒ <code>provide</code> 够不到， <code>evoke()</code> 恒返回 <code>null</code>（表现为「点按钮毫无反应」，不报错也不崩）。</p><p>Porter 挂载时读直系父的 <code>data-dc-slot</code>，命中方位槽即报：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ModalPorter] 它被放在 AppPage 的 #top 槽里 —— 方位槽是 ModalShelf 的兄弟节点，</span></span>\n<span class="line"><span>provide 够不到，evoke() 恒为 null（表现为「点按钮毫无反应」，不报错不崩）。</span></span>\n<span class="line"><span>[MUST] 移到**默认槽**（page 架子就住在默认槽里；与 AppPage 并列同样够不到）。</span></span>\n<span class="line"><span>Porter 自身零 DOM 输出，放默认槽里不占任何版面。</span></span></code></pre></div><ul><li><strong>方位槽里放 Porter 没有任何正当用法</strong> ⇒ 这条恒报（不限 dev），且零误报</li><li>默认槽 / 脱离 <code>AppPage</code> 单用 ⇒ <strong>零输出</strong></li><li>🔴 出口是<strong>默认槽</strong>，[MUST NOT] 顺手改成「与 <code>AppPage</code> 并列」—— page 架子 （<code>ModalShelf level=&quot;page&quot;</code>）就住在 AppPage 的默认槽里，并列<strong>同样够不到</strong>， <code>evoke()</code> 一样恒为 null。「与 AppPage 并列」只对<strong>不需要 page 架子</strong>的东西成立 （声明式挂载、自己 teleport 走的弹窗组件）</li><li>「弹窗经弹层挂载、不占版面 ⇒ 放哪都行」是<strong>只对了一半</strong>的推理：弹窗自身 teleport 走了， 但<strong>槽本身</strong>照样渲染（fixed + padding + 背景），白占一条高度 —— 见 <code>AppPage</code> 文档的空壳槽检测</li></ul><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong>未注册 key 是静默失败面</strong>：<code>evoke</code> 返回 null + console.error——消费侧 [MUST] 判空（<code>evoke(...)?.close()</code> 或先判 null），别假设一定成功</li><li><strong>shelf 字符串只认 &quot;app&quot;/&quot;page&quot;</strong>：custom 架子必须传 <code>ShelfInstance</code>（ref 实例），传字符串进 custom 寻址不通</li><li><strong>key 类型必须声明合并</strong>：evoke 的 key 泛型约束 <code>keyof ModalShelfMap</code>——业务 [MUST] 在 <code>.d.ts</code> 里 declare module 扩展 <code>ModalShelfMap</code>（见 ModalShelf 文档），否则 key 不在 map 上 TS 直接拦截</li><li><strong>自动清理别补偿</strong>：Porter 失活/卸载已自动 remove 全部 nsKey，手写 <code>onUnmounted</code> 清理是重复劳动（也可能提前清掉活跃弹窗）</li><li><strong>页面级 Porter [MUST NOT] 配 <code>shelf:&quot;app&quot;</code> 条目</strong>：页面卸载后弹窗仍挂在常驻 app 架子上 → 孤儿弹窗（唤起句柄已死、只剩弹窗自身 closeFn）；app 级弹窗唯一正道 = AppLayout <code>globalModalConfig</code> + 内部专用 Porter + <code>globalModalRemote</code> 遥控</li><li><strong>[MUST NOT] 把 Porter 放进 <code>AppPage</code> 的 <code>#top</code>/<code>#bottom</code>/<code>#left</code>/<code>#right</code></strong>：方位槽够不到 page 架子（<code>evoke()</code> 恒 null），且槽本身白占版面；挂载时会有一条点名报错。出口是<strong>默认槽</strong>（Porter 零 DOM 输出，放那里不占任何版面）—— [MUST NOT] 改成「与 <code>AppPage</code> 并列」，page 架子就在默认槽里、并列同样够不到</li><li><strong>弹窗 UI 不在 Porter 插槽里写</strong>：Porter 只是注册表宿主，弹窗经 evoke 落在架子上渲染——插槽只放页面内容</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>架子宿主：<code>ModalShelf</code>（level 层级 + ModalShelfMap declare merge + evoke/remove/close + sameKeyStrategy）</li><li>注入契约：<code>ModalInjectedProps&lt;P&gt;</code>（show/closeFn/removeFn/payload，架子注入弹窗组件）</li><li>句柄：<code>EvokeHandle</code>（close / update 增量合并，不 remount）</li><li>弹窗组件族：<code>ModalConfirm</code> / <code>ModalForm</code> / <code>ModalDetail</code>（作注册表 item；DetailModalItem 薄适配器范式见 <code>list-layout/guide/</code>）</li><li>类型：<code>RegisterEntry&lt;K&gt;</code>、<code>ModalSameKeyStrategy</code>（&quot;recreate&quot; 默认 / &quot;update&quot; 整体替换 props 不 remount）</li><li>范式页：<code>apps/reference/src/pages/modal/porter/showcase/</code>、<code>apps/reference/src/pages/modal/guide/</code></li></ul>',40)])])}const u=o(l,[["render",s]]);export{g as __pageData,u as default};
